return ['domain'=>NULL,'plural-forms'=>'nplurals=4; plural=(n % 100 == 1) ? 0 : ((n % 100 == 2) ? 1 : ((n % 100 == 3 || n % 100 == 4) ? 2 : 3));','language'=>'hsb','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:17+00:00','po-revision-date'=>'2026-10-31T05:53:17+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Wupołni falowace přełožki za pluginy a drasty, kotrež su na wašim sydle hižo instalowane.','Translations'=>'Přełožki','Babilim Settings'=>'Nastajenja Babilim','Settings'=>'Nastajenja','You are not allowed to do this.'=>'Nimaće dowolnosć, to činić.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Wubjerće mjenje komponentow: maksimalnje %1$d operacijow na běh (wubrali sće %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Tuta komponenta na tutym sydle zainstalowana njeje, a tohodla njeda so za nju přełožk požadać.','Already installed.'=>'Hižo instalowane.','Downloaded and installed.'=>'Sćahnjene a instalowane.','Babilim has not been enabled for this site yet.'=>'Babilim njeje so za tute sydło hišće aktiwizował.','No build is available to download for this locale.'=>'Za tutu rěč njeje žadyn build za sćahnjenje k dispozicii.','Rolled back to the previous build.'=>'Wróćo stajene na předchadny build.','Rolled back and reported.'=>'Wróćo stajene a zdźělene.','Rolled back, but the report could not be sent: %s'=>'Wróćo stajene, ale zdźělenka njeje so dała pósłać: %s','Removed.'=>'Wotstronjene.','Translation requested.'=>'Přełožk požadany.','This component was already uploaded. Babilim is checking it now.'=>'Tuta komponenta bu hižo nahrata. Babilim ju nětko přepruwuje.','Upload cancelled.'=>'Nahraće přerušene.','Upload complete — translation requested.'=>'Nahraće dokónčene – přełožk požadany.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Tuta komponenta wersijowe čisło njedeklaruje, a tohodla njeda so za nju přełožk požadać.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Wersijowe čisło tuteje komponenty je dlěše hač %d znamješkow, štož Babilim njemóže předźěłać, a tohodla njeda so za nju přełožk požadać.','A translation cannot be requested for that locale on this site right now.'=>'Přełožk za tutu rěč njemóže so tuchwilu na tutym sydle požadać.','Thank you. Your report was sent.'=>'Dźakujemy so. Waša zdźělenka bu pósłana.','This report does not name a valid plugin or theme and locale.'=>'Tuta zdźělenka njewunjenuje płaćiwy plugin abo drastu a rěč.','Please choose a category for this report.'=>'Prošu wubjerće kategoriju za tutu zdźělenku.','This report is missing a valid build to report against.'=>'Tutej zdźělence faluje płaćiwy build, na kotryž so pośahuje.','This build is not one this site currently knows about for this component/locale.'=>'Tutón build tute sydło za tutu komponentu/rěč mjeztym njezna.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Polo "%1$s" je předołho: ma %2$d znamješkow a limit je %3$d. Ničo njebu pósłane; prošu skrótšće je a spytajće hišće raz.','Original string'=>'Originalny rjećazk','String context'=>'Kontekst znamješkoweho rjećazka','Current translation'=>'Aktualny přełožk','Suggested translation'=>'Namjetowany přełožk','Note (optional)'=>'Zapiska (opcionalnje)','Where you saw this (optional)'=>'Hdźe sće to widźał (opcionalnje)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Synchronizacija Babilim je přez słužbu nachwilnje wotkładowana (limitowanje); spyta so znowa po %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'To płaćiwy kod rěče WordPress njeje. Ničo njebu składowane.','Settings saved.'=>'Nastajenja składowane.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Jeli je to zapnjene, wotinstalowanje tež identitu tutoho sydła zhaša. Płaćena licenca, kotraž je z tutym sydłom zwjazana, njeda so potom awtomatisce wobnowić; dyrbjał byšće so z podpěru Babilim na %s do zwiska stajić, zo byšće ju wróćo dóstał.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim je nastajeny, zo by identitu tutoho sydła zhašał, hdyž so tykač zhaša. Płaćena licenca, kotraž je z tutym sydłom zwjazana, njemóhła so potom awtomatisce wobnowić; dyrbjeli byšće so z podpěru Babilim na %s do zwiska stajić. Zo byšće identitu wobchowali, klikńće na Přetorhnyć, wotkliknće hódnotu „Při wotinstalowanju wšě daty Babilim zhašeć“ w nastajenjach Babilim a deaktiwujće hišće raz. Tola deaktiwować?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d sydło w tutej syći je nastajene, zo by swoju identitu Babilim zhašało, hdyž so tykač zhaša. Płaćena licenca, kotraž je z tutym sydłom zwjazana, njemóhła so potom awtomatisce wobnowić; dyrbjeli byšće so z podpěru Babilim na %2$s do zwiska stajić. Zo byšće identitu wobchowali, klikńće na Přetorhnyć, wotkliknće hódnotu „Při wotinstalowanju wšě daty Babilim zhašeć“ w nastajenjach Babilim tutoho sydła a deaktiwujće hišće raz. Tola deaktiwować?' . "\0" . '%1$d sydle w tutej syći stej nastajenej, zo bystej swoju identitu Babilim zhašałoj, hdyž so tykač zhaša. Płaćena licenca, kotraž je z tymaj sydloma zwjazana, njemóhła so potom awtomatisce wobnowić; dyrbjeli byšće so z podpěru Babilim na %2$s do zwiska stajić. Zo byšće identity wobchowali, klikńće na Přetorhnyć, wotkliknće hódnotu „Při wotinstalowanju wšě daty Babilim zhašeć“ w nastajenjach Babilim kóždeho sydła a deaktiwujće hišće raz. Tola deaktiwować?' . "\0" . '%1$d sydła w tutej syći su nastajene, zo bychu swoju identitu Babilim zhašeli, hdyž so tykač zhaša. Płaćena licenca, kotraž je z tutymi sydłami zwjazana, njemóhła so potom awtomatisce wobnowić; dyrbjeli byšće so z podpěru Babilim na %2$s do zwiska stajić. Zo byšće identity wobchowali, klikńće na Přetorhnyć, wotkliknće hódnotu „Při wotinstalowanju wšě daty Babilim zhašeć“ w nastajenjach Babilim kóždeho sydła a deaktiwujće hišće raz. Tola deaktiwować?' . "\0" . '%1$d sydłow w tutej syći je nastajenych, zo bychu swoju identitu Babilim zhašeli, hdyž so tykač zhaša. Płaćena licenca, kotraž je z tutymi sydłami zwjazana, njemóhła so potom awtomatisce wobnowić; dyrbjeli byšće so z podpěru Babilim na %2$s do zwiska stajić. Zo byšće identity wobchowali, klikńće na Přetorhnyć, wotkliknće hódnotu „Při wotinstalowanju wšě daty Babilim zhašeć“ w nastajenjach Babilim kóždeho sydła a deaktiwujće hišće raz. Tola deaktiwować?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Tuta syć ma přewjele sydłow, zo bychmy je jednotliwje přepruwowali, a někotre z nich móhli być nastajene, zo bychu swoju identitu Babilim zhašeli, hdyž so tykač zhaša. Płaćena licenca, kotraž je z takim sydłom zwjazana, njemóhła so potom awtomatisce wobnowić; dyrbjeli byšće so z podpěru Babilim na %s do zwiska stajić. Zo byšće identity wobchowali, klikńće na Přetorhnyć, wotkliknće hódnotu „Při wotinstalowanju wšě daty Babilim zhašeć“ w nastajenjach Babilim kóždeho sydła a deaktiwujće hišće raz. Tola deaktiwować?','Open Babilim settings'=>'Nastajenja Babilim wotewrěć','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim njemóžeše tute sydło přepruwować, tohodla so ničo njesćahnje ani njeinstaluje.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Słužba njemóžeše waše sydło docpěć. Firewall, zawěsćenski tykačk abo prawidło hostinga najskerje naprašowanje blokuje; dowolće prošu naprašowanja na /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Waše sydło je přepozdźe wotmołwiło. Spytajće prošu pozdźišo hišće raz a přepruwujće, hač waš hosting njeje přepomały abo přećežowany.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Waše sydło je wotmołwiło, ale nic z tym, štož so wočakowaše. REST API móhł so přez druhi tykač přepisać abo móhł so tutón endpoint pufrować; wuzamkńće prošu /wp-json/babilim/v1/challenge z pufrowanja a přepisowanja.','Please check that your site can be reached from the internet, then try again.'=>'Přepruwujće prošu, hač je waše sydło z interneta docpějomne, a spytajće hišće raz.','Re-verify'=>'Znowa přepruwować','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Tute sydło přesahuje wulkosć, kotruž słužba w jednej synchronizaciji akceptuje, tohodla su so někotre zapiski wuwostajili: %1$d komponentow a %2$d rěčow.','This site is verified.'=>'Tute sydło je přepruwowane.','Registration restarted.'=>'Registrowanje bu znowa startowane.','Sync complete.'=>'Synchronizacija je dokónčena.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim tute sydło aktiwizuje a přepruwuje… Začitajće stronu znowa abo čakajće na kónc planowaneho přepruwowanja.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim njemóžeše aktiwizowanje dokónčić (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Hosting, kotryž jenož jedne naprašowanje PHP naraz wobdźěłuje, njemóže tutón krok dokónčić.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim je zapnjeny: sydło je wobkrućene a %d komponenta bu namakana.' . "\0" . 'Babilim je zapnjeny: sydło je wobkrućene a %d komponenće staj so namakałoj.' . "\0" . 'Babilim je zapnjeny: sydło je wobkrućene a %d komponenty bu namakane.' . "\0" . 'Babilim je zapnjeny: sydło je wobkrućene a %d komponentow bu namakanych.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim je deaktiwizowany. Nic wjace so njesćele; hižo instalowane přełožki dale fungowaja.','Supplementary translation index rebuilt.'=>'Dodatny index přełožkow bu znowa natwarjeny.','Sweep complete: %d file deleted.'=>'Přepytowanje dokónčene: %d dataja zhašana.' . "\0" . 'Přepytowanje dokónčene: %d dataji zhašanej.' . "\0" . 'Přepytowanje dokónčene: %d dataje zhašane.' . "\0" . 'Přepytowanje dokónčene: %d datajow zhašanych.','Removed %d installed component.'=>'%d instalowana komponenta bu wotstronjena.' . "\0" . '%d instalowanej komponenće buštej wotstronjenej.' . "\0" . '%d instalowane komponenty buchu wotstronjene.' . "\0" . '%d instalowanych komponentow bu wotstronjenych.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Awtomatiske instalacije su nětko wupnjene; zapńće je w nastajenjach zaso, jeli chceće.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim namaka na tutym sydle tykače a drasty, kotrež nimaja přełožk za wašu rěč, a za kóždy tykač a kóždu drastu přełožk instaluje.','Languages found on this site: %s.'=>'Rěče namakane na tutym sydle: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Dostupne přełožki da so z jednym kliknjenjom instalować a falowace da so požadać. Potom so nowe přełožki a aktualizacije awtomatisce instaluja (w darmotnym planje jenož za tykače a drasty, kotrež hižo swobodne městno wužiwaja).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Darmotny plan wobsahuje wobmjezowanu ličbu tykačow a drastow; waša dokładna kwota so w Nastajenjach pokazuje, po tym zo sće Babilim zapnył.','What is sent when you enable Babilim'=>'Štož so sćele, hdyž Babilim zapnjeće','Enabling…'=>'Aktiwizuje so…','Enable Babilim'=>'Babilim zapnyć','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Hdyž na Aktiwizować kliknjeće, sće z tym přezjedni, zo so horjeka naspomnjene informacije na Babilim sćelu.','Check again now'=>'Nětko hišće raz přepruwować','Babilim installed %d translation automatically since your last visit.'=>'Babilim je wot wašeho poslednjeho wopyta awtomatisce %d přełožk instalował.' . "\0" . 'Babilim je wot wašeho poslednjeho wopyta awtomatisce %d přełožkaj instalował.' . "\0" . 'Babilim je wot wašeho poslednjeho wopyta awtomatisce %d přełožki instalował.' . "\0" . 'Babilim je wot wašeho poslednjeho wopyta awtomatisce %d přełožkow instalował.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim tute sydło aktiwizuje a přepruwuje… (poslední spyt: %s)','Check again'=>'Hišće raz přepruwować','No components synced yet.'=>'Hišće žane komponenty synchronizowane.','%d succeeded'=>'%d wuspěšny' . "\0" . '%d wuspěšnej' . "\0" . '%d wuspěšne' . "\0" . '%d wuspěšnych','%d skipped'=>'%d přeskočeny' . "\0" . '%d přeskočenej' . "\0" . '%d přeskočene' . "\0" . '%d přeskočenych','%d failed'=>'%d njewuspěšny' . "\0" . '%d njewuspěšnej' . "\0" . '%d njewuspěšne' . "\0" . '%d njewuspěšnych','%d not yet tried'=>'%d hišće njespytany' . "\0" . '%d hišće njespytanej' . "\0" . '%d hišće njespytane' . "\0" . '%d hišće njespytanych','%1$s nothing to do.'=>'%1$s ničo činić njetrjeba.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Hromadne sćahnjenje:','Bulk update:'=>'Hromadna aktualizacija:','Bulk request:'=>'Hromadne požadanje:','per day'=>'na dźeń','Wrong meaning'=>'Wopačny zmysł','Wrong term'=>'Wopačny terminus','Broken placeholder'=>'Wobškodźeny zastupnik','Wrong for this context'=>'Wopačne za tutón kontekst','Wrong plural form'=>'Wopačna pluralowa forma','Negation reversed'=>'Wobroćena negacija','Translation does not load'=>'Přełožk so njezačita','problem report categoryOther'=>'Druhe','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Pokračuje so…','Continue next batch (%d left)'=>'Z přichodnej dawku pokročować (%d zbywa)','Search components'=>'Komponenty pytać','These are the languages this site uses. You can change them in %s.'=>'To su rěče, kotrež tute sydło wužiwa. Móžeće je w %s změnić.','Upload this component?'=>'Tutu komponentu nahrać?','There is no upload waiting for confirmation.'=>'Žane nahraće njeceka na wobkrućenje.','Back'=>'Wróćo','To translate this component, Babilim needs its source.'=>'Zo by so tuta komponenta přełožiła, trjeba Babilim jeje žórło.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Cyly zapis wtyčnika abo drasty %1$s (wersija %2$s) so na Babilim nahraje.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Jeli tutón zapis kluče, protokole abo daty kupcow wobsahuje, so tež nahrawaja. Słužba wšědne citliwe dataje (konfiguracija, wokolina, wotćahi datowych bankow, protokole, kluče) wotstroni, ale njemóže zaručić, zo wšitko namaka.','The upload is kept until you ask Babilim to delete it.'=>'Nahraće so tak dołho wobchowa, doniž Babilim njepopytaće, zo by so zhašało.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Hostowanski poskićowar słužby je składuje a modele AI je předźěłaja, zo bychu přełožk wutworili.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Originalny tekst a přełožki z njeho wutworjene so druhim sydłam poskića, kotrež samsnu wersiju instaluja.','By continuing you confirm that you have the right to upload this component.'=>'Přez pokročowanje wobkrućeće, zo maće prawo, tutu komponentu nahrać.','Upload and request'=>'Nahrać a požadać','Uploading…'=>'Nahrawa so…','Cancel'=>'Přetorhnyć','Uploading'=>'Nahrawa so','There is no upload in progress.'=>'Žane nahraće njeběži.','Uploading part %1$d of %2$d…'=>'Nahrawa so dźěl %1$d z %2$d…','Continue'=>'Pokročować','Confirm'=>'Wobkrućić','Remove'=>'Wotstronić','Roll back'=>'Wróćo stawić','Nothing to confirm.'=>'Nic k wobkrućenju.','Choose a language'=>'Rěč wubrać','Roll back and report'=>'Wróćo stawić a zdźělić','Report a problem'=>'Problem zdźělić','Nothing to choose.'=>'Nic k wubranju.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Wubjerće rěč.','Supplementary translations'=>'Přidatne přełožki','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Swójski přinošk kóždeje komponenty k zhromadnemu přidatkej standardneje domeny kóždeje rěče.','Component'=>'Komponenta','Language'=>'Rěč','Included in index'=>'W indexu zapřijaty','Entries'=>'Zapiski','Conflicting keys'=>'Konfliktowe kluče','Yes'=>'Haj','No — component inactive'=>'Ně — komponenta je inaktiwna','No — installed version differs from the active one'=>'Ně — instalowana wersija so wot aktiwneje rozeznawa','No — component removed'=>'Ně — komponenta je wotstronjena','No'=>'Ně','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Jenož administrator syće móže to činić, dokelž to přełožkowe dataje změnja, kotrež wšě sydła w tutej syći zhromadnje wužiwaja.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim njemóžeše přepruwowanje tutoho sydła dokónčić (słužba njemóžeše so wróćo zwjazać). Registrowanje je zastajene.','This site already has an active registration that can no longer be recovered automatically.'=>'Tute sydło ma hižo aktiwne registrowanje, kotrež njeda so awtomatisce wobnowić.','Restart registration'=>'Registrowanje znowa startować','Babilim settings'=>'Nastajenja Babilim','General'=>'Powšitkowne','Advanced'=>'Rozšěrjene','Languages'=>'Rěče','Automatic installs'=>'Awtomatiske instalacije','Install available translations automatically'=>'Dostupne přełožki awtomatisce instalować','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'W darmotnym planje so jenož komponenty awtomatisce instaluja, kotrež hižo jedyn z twojich darmotnych slotow wužiwaja, tak zo so žadyn nowy slot njewobsadźa.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Tute sydło je dźěl multisite-sćeže, kotraž nowe přełožki awtomatisce njeinstaluje. Hižo instalowane přełožki so ale dale aktualizuja.','Custom overrides'=>'Swójske přepisanja','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Moje swójske přepisanja přełožkow wobchować, hdyž so wšitko zhaša abo so tutón plugin wotinstaluje.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Přełožkowe dataje, kotrež do %s stajiš, maja přeco přednosć před datajemi Babilim. Wobchowaja so, chibazo znamješko z tutoho kontrolneho kašćika wotstroniš.','Uninstall'=>'Dejinstalować','Delete all Babilim data on uninstall'=>'Při wotinstalowanju wšě daty Babilim zhašeć','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Po standardźe wupinjene: při zhašenju plugina so identita tutoho sydła wobchowa, tak zo so móže při nowej instalaciji zaso wužiwać.','Account'=>'Konto','Save changes'=>'Změny składować','Disable Babilim'=>'Babilim wupnyć','Installed translations are kept, but no further checks or downloads will run.'=>'Instalowane přełožki so wobchowaja, ale dalše kontrole abo sćehnjenja so njewjedu.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim wupnyć? Instalowane přełožki so wobchowaja, ale dalše kontrole abo ściahnjenja so njewuwjedu.','This site is not registered with Babilim yet.'=>'Tute sydło hišće njeje pola Babilim registrowane.','This site is already licensed. Reload the page.'=>'Tute sydło je hižo licencowane. Zaladuj stronu znowa.','Checkout is not available for this site right now.'=>'Zapłaćenje za tute sydło tuchwilu k dispoziciji njesteji.','Could not start checkout: %s'=>'Zapłaćenje njeje so dało startować: %s','Babilim is not enabled.'=>'Babilim njeje zmóžnjeny.','Not registered yet'=>'Hišće njeregistrowany','Not verified'=>'Njepřepruwowany','Verified'=>'Přepruwowany','Status'=>'Status','Licensed'=>'Licencowany','Partner'=>'Partner','Free'=>'Darmotny','License'=>'Licenca','Upgrade this site'=>'Licencu tutoho sydła aktualizować','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Jednorazowy nakup za to sydło: %1$s %2$s. Zapřijima wšě přichodne aktualizacije přełožkow. Płaćenje wobdźěłuje Paddle w nowym rajtarku.','This issues a new restore code and the previous one stops working. Continue?'=>'Tak so nowy kod za wobnowjenje wudawa a předchadny přestanje fungować. Pokročować?','Show a new restore code'=>'Nowy kod za wobnowjenje pokazać','rc_…'=>'rc_…','Restore code'=>'Kod za wobnowjenje','Restore purchase'=>'Kupu wobnowić','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Sće hižo licencu za tutu domenu kupił? Zapodajće kod za wobnowjenje, kotryž sće při płaćenju dostał.','That does not look like a restore code.'=>'To njewupada kaž kod za wobnowjenje.','This restore code was not recognised for this site.'=>'Tutón kod za wobnowjenje njebu za to sydło spóznaty.','Too many attempts. Try again tomorrow.'=>'Přewjele pospytow. Spytajće jutře znowa.','This site must be verified first.'=>'Tute sydło dyrbi so najprjedy přepruwować.','Could not restore the purchase: %s'=>'Nakup njeda so wobnowić: %s','Purchase restored. This site is now licensed.'=>'Nakup wobnowjeny. Tute sydło je nětko licencowane.','This site has no purchase to show a code for.'=>'Tute sydło nima nakupa, za kotryž by so móhł kod pokazać.','Could not show a new restore code: %s'=>'Nowy kod za wobnowjenje njeda so pokazać: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Waš nowy kod za wobnowjenje: %s. Wuchowajće jón na wěstym městnje — předchadny kod wjace njefunguje.','What is sent when Babilim checks this site'=>'Što so sćele, hdyž Babilim to sydło přepruwuje','(detected)'=>'(spóznate)','No language is managed yet.'=>'Hišće so žana rěč njezarjaduje.','Babilim adds translations for every language checked here.'=>'Babilim přidawa přełožki za kóždu tu wubrane rěč.','Add another language'=>'Dalšu rěč přidać','Choose a language…'=>'Wubjerće rěč…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Połny lisćina lokalow WordPress.org njeda so ze słužby začitać, tohodla njeda so tuchwilu žana druha rěč přidać.','Theme'=>'Drasta','Plugin'=>'Tykač','Free quota'=>'Darmotna kwota','Downloads: %1$d/%2$d (%3$s)'=>'Ściahnjenja: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Index přidatnych přełožkow','Built'=>'Wutworjene','Included'=>'Zapřijate','Excluded'=>'Wuzamknjeny','Already in WordPress core'=>'Hižo w jādrje WordPress','Supplementary translation maintenance'=>'Wothladowanje přidatnych přełožkow','Maintenance status is not available right now.'=>'Status wothladowanja tuchwilu njeje k dispozicii.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Čisćenje bu %1$s zastajene: %2$s. Ničo njebu zhašane.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Poslednje wučišćenje dnja %1$s: nowo markěrowane dataje: %2$d; zhašane dataje: %3$d; wotstronjene zapiski: %4$d.','No cleanup has run yet.'=>'Hišće žane wučišćenje njebě.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Zapis do indeksa přełožkow je so dnja %1$s (%2$s) z druhim požadanjom skonfliktował a njebu nałožowany; najnowša wersija bu zachowana.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Zapis do indeksa přełožkow dnja %1$s (%2$s) njeda so dokónčić a njebu nałožowany (%3$s).','Maintenance'=>'Wothladowanje','Rebuild index now'=>'Indeks nětko natwarić','Sweep now'=>'Nětko přepytać','Danger zone'=>'Strachotna zona','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Zhaša wšě rěčne dataje, kotrež je Babilim za kóždy tykač a drastu na tutym sydle instalował.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Chceće wšitko wotstronić, štož je Babilim instalował? Tuta akcija zhaša wšě rěčne dataje, kotrež je za kóždy tykač a drastu na tutym sydle instalował.','Remove everything Babilim installed'=>'Wšitko wotstronić, štož je Babilim instalował','This string is too long to be sent as a report, so no report form is offered for it.'=>'Tutón znamješkowy rjećazk je za rozprawu přejara dołhi, tohodla so za njón žadyn formular rozprawy njeposkića.','Category'=>'Kategorija','Choose a category…'=>'Wubjerće kategoriju…','Roll back and send report'=>'Wróćo stajić a rozprawu pósłać','Send report'=>'Rozprawu pósłać','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Dźěl teksta tuteje komponenty je wot awtora fiksnje zapisany a njehodźi so z rěčnym pakćikom přełožić.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Z drastu sobu dodate','Bundled with the plugin'=>'Z tykačom sobu dodate','Upload was not accepted'=>'Nahraće njebu akceptowane','Upload expired before it finished'=>'Nahraće je spadnyło, prjedy hač je so dokónčiło','No translation'=>'Žadyn přełožk','Upload in progress — continue or cancel'=>'Nahraće běži — pokročować abo přetorhnyć','Scheduled, waiting to be processed'=>'Planowany, čaka na předźěłanje','Translating…'=>'Přełožuje so…','Translation failed'=>'Přełožowanje njeje so poradźiło','Free quota used'=>'Darmotna kwota wužita','Needs a paid license'=>'Trjeba płaćenu licencu','Not supported'=>'Njepodpěrany','Status unknown'=>'Status njeznaty','translation statusInstalled'=>'Instalowany','Update available'=>'Aktualizacija k dispoziciji','Removed after a failed integrity check'=>'Po njeporadźenej kontroli integrity wotstronjeny','Installed · built for %s, new version scheduled'=>'Instalowany · za %s twórjeny, nowa wersija je planowana','Installed · built for a different version, new version scheduled'=>'Instalowany · za druhu wersiju twórjeny, nowa wersija je planowana','Installed · built for %s, translating the new version…'=>'Instalowany · za %s twórjeny, nowa wersija so přełožuje…','Installed · built for a different version, translating the new version…'=>'Instalowany · za druhu wersiju twórjeny, nowa wersija so přełožuje…','Installed · built for %1$s, this site has %2$s'=>'Instalowany · za %1$s twórjeny, tute sydło ma %2$s','Installed · built for %s'=>'Instalowany · za %s twórjeny','Installed · built for a different version'=>'Instalowany · za druhu wersiju twórjeny','Installed · built for %s, new version failed'=>'Zainstalowany · za %s twórjeny, nowa wersija je so njeporadźiła','Installed · built for a different version, new version failed'=>'Instalowany · za druhu wersiju twořeny, nowa wersija je so njeporadźiła','Installed · built for %s, new version needs a paid license'=>'Instalowany · za %s twořeny, nowa wersija trjeba płaćenu licencu','Installed · built for a different version, new version needs a paid license'=>'Instalowany · za druhu wersiju twořeny, nowa wersija trjeba płaćenu licencu','Installed · built for %s, free quota used'=>'Instalowany · za %s wutworjeny, darmotna kwota wužita','Installed · built for a different version, free quota used'=>'Instalowany · za druhu wersiju wutworjeny, darmotna kwota wužita','translation statusAvailable'=>'K dispozicii','Installed · %s'=>'Instalowany · %s','Available · %s'=>'K dispozicii · %s','Update'=>'Aktualizować','Download'=>'Sćahnyć','Updating…'=>'Aktualizuje so…','Downloading…'=>'Sćahuje so…','Retry request'=>'Požadanje hišće raz spytać','Request newer translation'=>'Nowši přełožk požadać','Request translation'=>'Přełožk požadować','Requesting…'=>'Požaduje so…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Požadanje přełožka wužiwa jedyn z wašich darmotnych slotow, chiba zo tuta komponenta hižo jedyn wužiwa. Njeporadźeny přełožk slot njewróća.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Jeli tuta komponenta hišće jedyn z wašich darmotnych slotow njewužiwa, wužiwa požadanje přełožka jedyn. Njeporadźeny přełožk slot njewróća. Pokročować?','No plugins or themes found.'=>'Žane tykače abo drasty namakane.','Clear filters'=>'Filtry wotstronić','No components match these filters. %s'=>'Žane komponenty tutym filtram njewotpowědują. %s','Select all'=>'Wšě wubrać','All'=>'Wšě','Available'=>'K dispozicii','Updates'=>'Aktualizacije','Requestable'=>'Móžno požadować','Installed'=>'Instalowany','Plugins'=>'Tykače','Themes'=>'Drasty','All languages'=>'Wšě rěče','%d to install'=>'%d k instalowanju' . "\0" . '%d k instalowanju' . "\0" . '%d k instalowanju' . "\0" . '%d k instalowanju','Language:'=>'Rěč:','Bulk actions apply to every matching language of each selected component.'=>'Hromadne akcije płaća za kóždy wotpowědny rěč kóždeje wubranej komponenty.','Bulk actions apply only to the selected language of each selected component.'=>'Hromadne akcije płaća jenož za wubranu rěč kóždeje wubranej komponenty.','Version %s'=>'Wersija %s','Theme · %s'=>'Drasta · %s','Plugin · %s'=>'Tykač · %s','Remove the %2$s translation of %1$s from this site?'=>'Přełožk %2$s za %1$s z tutoho sydła wotstronić?','Roll back the %2$s translation of %1$s to the previous build?'=>'Přełožk %2$s za %1$s na předchadny staw wróćo stajić?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Registrowanska wužadanje nima wočakowanu formu.','That is not a valid build identifier.'=>'To njeje płaćiwy identifikator wersije.','Refusing to write outside the Babilim language-file directory.'=>'Pisanje zwonka zapisnika rěčnych datajow Babilim so wotpokazuje.','Could not write the downloaded package to disk.'=>'Sćahnjeny paket njeda so na dysk pisać.','Unexpected HTTP %d response.'=>'Njewočakowana HTTP-wotmołwa %d.','This site\'s URL, so the service can verify you own it.'=>'URL tutoho sydła, zo by słužba móhła přepruwować, zo jón wy wobsedźiće.','Your WordPress version, to serve compatible translation files.'=>'Waša wersija WordPress, zo bychu so kompatibelne přełožkowe dataje podali.','Your PHP version, for compatibility.'=>'Waša wersija PHP, za kompatibilitu.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Wersija tutoho tykača samoho, zo by słužba mohła poručić jón aktualizować, jeli je přestara za komunikaciju.','This site\'s configured locale.'=>'Konfigurowana rěčna wersija tutoho sydła.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Kóžda rěč, kotraž so na tutym sydle wužiwa (rěč sydła, zainstalowane rěčne pakety, rěče wužiwarjow a wšě, kotrež sami přidawaće). Z žanej rěču so njewobchadźa hinak hač z druhej.','(a public key generated for this site)'=>'(zjawny kluč, generowany za tute sydło)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Zjawny kluč instalacije tutoho sydła, kotryž so wužiwa, zo by so dopokazało, zo naprašowanja woprawdźe z tutoho sydła pochadźeja. Sćele so jenož zjawna połojca.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Kóžda instalowana tykačowa/drastowa komponenta: jeje slug, wersija, tekstowa domena/tekstowe domeny, hač je zapisk na wp.org, jeje swójske zapakowane rěčne wersije a za kotre rěčne wersije sće hižo přełožk Babilim instalowali.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Jenož hdyž nahraće za tykač abo drastu, kotraž njeje na WordPress.org, wobkrućiće: cyły zapisnik tuteje komponenty jako zip.','(generic codes and coordinates only)'=>'(jenož generiske kody a koordinaty)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Hač do 20 čakacych diagnostiskich podawkow (n.př. dataja, kotraž kontrolu integrity njewobstała), kóždy jenož z kodom, komponentu a rěčnej wersiju, a ženje ze žanym wobsahom znamješkowych rjećazkow abo přełoženym tekstom.','Unsafe locale: %s'=>'Njebezpječna rěčna wersija: %s','Manifest unavailable: %s'=>'Manifest njeje k dispoziciji: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Aktiwne komponenty njejsu so dali zwěsćić; eksistowacy zjednoćeny indeks wosta njezměnjeny.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Zainstalowane tykače/drasty njejsu so dali zwěsćić; čisćenje so přeskoči, ničo so njewušmórny.','Sweep aborted without orphaning anything: %s.'=>'Přehladanje bu přetorhnjene bjez wosyroćenja něčeho: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Wučisćenje je so wuwjedło, ale někotre z jeho změnow njebě móžno do indeksa přełožkow zapisać; přichodne wučisćenje to znowa spyta.','component kind in the sweep brake messagetheme'=>'drasta','component kind in the sweep brake messageplugin'=>'tykač','it would orphan every managed %1$s component (%2$d of %2$d)'=>'wosyroćiło by kóždu zrjadowanu komponentu %1$s (%2$d z %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'wosyroćiło by %1$d z %2$d zrjadowanych komponentow (wjace hač połojca)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Zjednoćeny index za \'%s\' bu přebudowany, ale index přełožkow njemóžeše jón zapisać; přichodna přebudowa spyta znowa.','Could not write the staged merged index.'=>'Posrjedkowany zjednoćeny index njebu móžno pisać.','Re-parsed entry count did not match the built index.'=>'Ličba zapiskow po znowaparsowanju njewotpowěduje natwarjenemu indeksej.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Zjednoćeny index za \'%s\' njebě móžno na městno přesunyć; předchadny index (jeli bě) bu wotstronjeny, zo by so połzaktualizowany stav wuwarował. Za tutu rěčnu wersiju so přidatk standardneje domeny njewužiwa, doniž so přebudowanje njeporadźi.','Could not open zip: %s'=>'Zip njeda so wočinić: %s','Zip has no manifest.json.'=>'Zip nima manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json w zipje njeje płaćiwy JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'\'%s\' w manifest.json njewotpowěduje wočakowanej hódnoće.','Another installation is running; try again in a moment.'=>'Druha instalacija běži; spytajće za wokomik znowa.','Not a valid server_build_id: %s'=>'Njeje płaćiwy server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Družina \'%1$s\' manifesta pakćika njewotpowěduje požadanej družinje \'%2$s\'.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Tekstowa domena pakćika \'%1$s\' njewotpowěduje kopiji komponenty na tutym sydle (\'%2$s\'), tohodla pakćik njebu instalowany.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Podata domena \'%1$s\' njewotpowěduje ani swójskemu slugej \'%2$s\' manifesta pakćika ani jeho text_domain \'%3$s\'.','Unsafe slug: %s'=>'Njebezpječny slug: %s','Unsafe text_domain: %s'=>'Njebezpječny text_domain: %s','The package has no %s for its own text domain.'=>'Pakćik nima %s za swoju tekstowu domenu.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json faluje abo ma njepłaćiwe \'%s\'.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json faluje abo ma njepłaćiwe \'entries\'.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json faluje abo ma njepłaćiwe \'files\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json faluje abo ma njepłaćiwe \'extra_domains\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json faluje abo ma njepłaćiwe \'build_no\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' w manifest.json njeje płaćiwy identifikator wersije.','manifest.json\'s \'contract\' is not a valid version string.'=>'\'contract\' w manifest.json njeje płaćiwy znamješkowy rjećazk wersije.','manifest.json\'s \'status\' must be \'published\'.'=>'\'status\' w manifest.json dyrbi być \'published\'.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'\'kind\' w manifest.json dyrbi być \'plugin\' abo \'theme\'.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json ma njepłaćiwe \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json ma njepłaćiwe \'default_domain_files\'.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest faluje abo ma njepłaćiwe \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' w expected_manifest njeje płaćiwy identifikator wersije.','No record for %s'=>'Žadyn zapis za %s','One or more served files no longer match the manifest.'=>'Jedna dataja abo wjacore słužene dataje njewotpowěduja hižo manifestej.','No previous build to roll back to.'=>'Žadyn předchadny build za wróćostajenje njeje.','The change could not be recorded in the translation index; please try again.'=>'Změnu njebu móžno do indeksa přełožkow zapisać; prošu spytajće hišće raz.','Unknown kind: %s'=>'Njeznaty typ: %s','Unsafe domain: %s'=>'Njebezpječna domena: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Tekstowa domena \'%1$s\' (%2$s) stej hižo za druhu zainstalowanu komponentu (%3$s) k dispoziciji stajena; ničo njebu zainstalowane.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Wróćostajenje by \'%1$s\' (%2$s) přepisało, kotraž so nětko za druhu zainstalowanu komponentu (%3$s) wužiwa; ničo njebu změnjene.','Zip is missing expected file: %s'=>'W zipje wočakowana dataja faluje: %s','sha256 mismatch for %s'=>'Kontrolna suma sha256 za %s so njezhoduje','The package declares no main translation file.'=>'Paket žanu hłownu přełožkowu dataju njedeklaruje.','Zip is missing expected default file: %s'=>'W zipje faluje wočakowana Standard-dataja: %s','sha256 mismatch for default/%s'=>'sha256 njesouhlasuje za default/%s','Could not stage %s'=>'%s njeda so přihotować','Could not stage default/%s'=>'default/%s njeda so přihotować','Entry count mismatch for %s'=>'Ličba zapisow njewotpowěduje za %s','Could not verify entry count for %s'=>'Ličba zapisow za %s njeda so přepruwować','l10n.php entry count mismatch for %s'=>'Ličba zapisow l10n.php za %s so njezhoduje','Default supplement entry count mismatch.'=>'Ličba zapisow Standard-přidatka njewotpowěduje.','The package produced no servable main translation file.'=>'Paket njeje žanu hłownu přełožkowu dataju spłodźił, kotraž so hodźi podawać.','Could not prepare %s for rollback.'=>'%s njeda so za wróćostajenje přihotować.','Could not back up %s before replacing it.'=>'%s njeda so do narunanja zawěsćić.','Could not move %s into place.'=>'%s njeda so na městno přesunyć.','Could not read %s back after moving it into place.'=>'%s njeda so po přesunjenju na městno wróćo čitać.','English (United States)'=>'Jendźelšćina (Zjednoćene staty)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest njeje k dispoziciji: %s','could not read _manifest.json: %s'=>'_manifest.json njeda so čitać: %s','failed to parse _manifest.json: %s'=>'_manifest.json so njeda parsować: %s','_manifest.json has an unexpected structure'=>'_manifest.json ma njewočakowanu strukturu','Could not create the package archive.'=>'Paketowy archiw njeda so wutworić.','No writable temporary directory is available for packaging.'=>'Za paketowanje žadyn zapisujomny nachwilny zapis k dispoziciji njeje.','A file in the component could not be read, so it was not packaged.'=>'Dataja w komponenće njeda so čitać, tohodla njebu zapakowana.','Only plugins and themes can be packaged.'=>'Jenož tykače a drasty hodźa so zapakować.','The component\'s main file was not found.'=>'Hłowna dataja komponenty njebu namakana.','The component is not inside the plugins or themes directory.'=>'Komponenta njeje w zapisu pluginow abo drastow.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim je za tutón krok čas přesahnył a budźe při přichodnym kontrolowanju pokročować.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim njemóžeše tute sydło přepruwować, tohodla so ničo njesćahnje ani njeinstaluje, doniž so přepruwowanje njeporadźi.','Registration response was missing required fields.'=>'W wotmołwje registracije trěbne pola faluja.','No pending challenge to verify.'=>'Žane čakace wužadanje za přepruwowanje njeje.','Verify response was missing site_token.'=>'W wotmołwje přepruwowanja site_token faluje.','No site id is on file to rotate a token for.'=>'Žadyn ID sydła za wuměnu tokena njeje składowany.','Rotate-token response was missing site_token.'=>'We wotmołwje na wuměnu tokena site_token faluje.','nonce must be a hexadecimal string.'=>'nonce dyrbi hexadecimalny znamješkowy rjećazk być.','No pending challenge for this nonce.'=>'Za tutón nonce žane čakace wužadanje njeje.','Too many requests.'=>'Přewjele naprašowanjow.','The service asked this site to wait before syncing again.'=>'Słužba je wot tutoho sydła požadała, zo by do dalšeje synchronizacije čakało.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Tute sydło ma %1$d komponentow w %2$d rěčach, štož trjeba %3$d pruwowanskich dawkow; Babilim móže maksimalnje %4$d na běh předźěłać. Redukujće zarjadowane rěče w nastajenjach abo deaktiwujće njewužiwane pluginy a drasty, a potom klikńće na Hišće raz přepruwować.','Babilim could not finish checking this site.'=>'Babilim njemóžeše kontrolowanje tutoho sydła dokónčić.','This site\'s address is too long for Babilim to register.'=>'Adresa tutoho sydła je za registraciju pola Babilim předołha.','This site\'s locale code is not one Babilim can register.'=>'Kod rěče tutoho sydła njeje tajki, kotryž móže Babilim registrować.','The download response was missing a usable location.'=>'W wotmołwje sćahnjenja wužiwajomne městno falowaše.','The service\'s upload offer was incomplete.'=>'Poskitk nahraća słužby běše njedospołny.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Tuta komponenta je wjetša hač słužba akceptuje, tohodla njeda so nahrać.','The packaged component could not be read.'=>'Zapakowana komponenta njeda so čitać.','A part of the upload kept failing, so the upload was cancelled.'=>'Dźěl nahraća so wospjetnje njeporadźi, tohodla bu nahraće přetorhnjene.','Could not read: %s'=>'Njeda so čitać: %s']];